/**
 * Builds the shipped character, "Pip", as an original glTF 2.0 binary.
 *
 *   npm run make:character
 *
 * Every vertex, material and animation clip in the output is generated by the
 * code below. Nothing is downloaded, imported, traced, datamined or converted
 * from anywhere: the geometry is revolved, swept and extruded from the profiles
 * in this file, the palette is chosen here, and the six pose clips are
 * keyframed here. That is the whole provenance of
 * `public/characters/pip/model.glb`, and it is why that one folder is the only
 * exception to the blanket ignore rule on public/characters.
 *
 * WHO PIP IS
 * A small apprentice wizard, drawn in chibi proportions — a head nearly half
 * the total height, very large eyes, a floppy pointed hat and a staff almost
 * too big to hold. Chibi is not a shortcut here, it is the right answer to the
 * actual constraint: this figure is drawn between 36 and 112 pixels wide, and
 * realistic proportions put the face in about nine pixels of that. A big head
 * and big eyes are what survive.
 *
 * Expression comes from the eyes, the eyebrows, the mouth and the hat. The
 * brows rotate, the eyes scale, there are two mouths that swap by scaling one
 * of them away, and the hat's tip is on its own node so it can flop. Between
 * them the six moods read without needing to read any words.
 *
 * No dependencies: a .glb is a 12-byte header, a JSON chunk and a binary
 * chunk, and node can write all three.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'characters', 'pip');

// ---------------------------------------------------------------------------
// Colour. glTF factors are LINEAR, not sRGB — handing it a hex triple directly
// is the classic way to get a washed-out model.
// ---------------------------------------------------------------------------
const srgbToLinear = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);

function linear(hex) {
  const h = hex.replace('#', '');
  return [0, 2, 4].map((i) => srgbToLinear(parseInt(h.slice(i, i + 2), 16) / 255));
}
const rgba = (hex, a = 1) => [...linear(hex), a];

/**
 * The palette, invented for this character.
 *
 * Chosen to silhouette on both extremes the app renders on — #fcfcfb in light
 * mode and #0d0d0d in dark — because the figure sits directly on a themed
 * surface with no card behind it. The deep violet hat and robe carry the
 * outline against white; the honey hair, gold band, cream face and cyan orb
 * carry it against black. Nothing in it is a single mid-tone that would vanish
 * against one of them.
 */
const PALETTE = {
  skin: '#ffddc2',
  skinShade: '#f0bf9e',
  hair: '#f2a65a',
  hairDark: '#c97e3c',
  robe: '#6c63c4',
  robeDark: '#4f489b',
  trim: '#a89cf0',
  hat: '#463c96',
  gold: '#ffd166',
  iris: '#2fb3cc',
  pupil: '#14202b',
  white: '#ffffff',
  blush: '#ff9aa2',
  mouth: '#b5455f',
  boot: '#332b57',
  wood: '#8a6a4a',
  orb: '#8df2ff',
};

const pbr = (hex, metallic = 0, roughness = 0.65, extra = {}) => ({
  pbrMetallicRoughness: { baseColorFactor: rgba(hex), metallicFactor: metallic, roughnessFactor: roughness },
  ...extra,
});

const MATERIALS = [
  { name: 'skin', ...pbr(PALETTE.skin, 0, 0.78) },
  { name: 'hair', ...pbr(PALETTE.hair, 0.04, 0.58) },
  { name: 'hairDark', ...pbr(PALETTE.hairDark, 0.04, 0.6) },
  { name: 'robe', ...pbr(PALETTE.robe, 0, 0.82) },
  { name: 'robeDark', ...pbr(PALETTE.robeDark, 0, 0.84) },
  { name: 'trim', ...pbr(PALETTE.trim, 0, 0.7) },
  // Thin shells, seen from underneath as often as from above.
  { name: 'hat', ...pbr(PALETTE.hat, 0, 0.8), doubleSided: true },
  { name: 'gold', ...pbr(PALETTE.gold, 0.55, 0.3, { emissiveFactor: linear(PALETTE.gold).map((c) => c * 0.12) }) },
  { name: 'iris', ...pbr(PALETTE.iris, 0.1, 0.28) },
  { name: 'pupil', ...pbr(PALETTE.pupil, 0.05, 0.25) },
  { name: 'sclera', ...pbr(PALETTE.white, 0, 0.42) },
  // The catchlights are what make a large flat eye read as an eye rather than
  // a disc, so they carry their own light and never fall into shadow.
  { name: 'glint', ...pbr(PALETTE.white, 0, 0.2, { emissiveFactor: linear(PALETTE.white) }) },
  { name: 'blush', ...pbr(PALETTE.blush, 0, 0.9) },
  { name: 'mouth', ...pbr(PALETTE.mouth, 0, 0.55) },
  { name: 'boot', ...pbr(PALETTE.boot, 0.05, 0.6) },
  { name: 'wood', ...pbr(PALETTE.wood, 0.05, 0.75) },
  { name: 'orb', ...pbr(PALETTE.orb, 0, 0.15, { emissiveFactor: linear(PALETTE.orb).map((c) => c * 1.0) }) },
  { name: 'skinShade', ...pbr(PALETTE.skinShade, 0, 0.8) },
];
const MAT = Object.fromEntries(MATERIALS.map((m, i) => [m.name, i]));

// ---------------------------------------------------------------------------
// Geometry.
//
// Three builders cover the whole character: revolve a profile around Y, sweep a
// circle along a 2D path, and extrude a 2D polygon. The first does almost all
// of it — a chibi is mostly spheres and cones.
// ---------------------------------------------------------------------------

/**
 * Revolve a profile of [radius, height] pairs around Y.
 *
 * Normals are computed analytically from the profile's own tangent rather than
 * by averaging face normals. That matters for a smooth surface: averaging
 * leaves a visible crease down the seam, because the duplicated ring of
 * vertices at 0 and 2π only ever receives contributions from one side of it.
 */
function lathe(profile, segments = 28) {
  const positions = [];
  const normals = [];
  const indices = [];
  const rows = profile.length;

  // Profile-space normal at each row: the tangent turned a quarter turn.
  const flat = profile.map((_, i) => {
    const [r0, y0] = profile[Math.max(0, i - 1)];
    const [r1, y1] = profile[Math.min(rows - 1, i + 1)];
    const [dr, dy] = [r1 - r0, y1 - y0];
    const len = Math.hypot(dr, dy) || 1;
    return [dy / len, -dr / len];
  });

  for (let s = 0; s <= segments; s++) {
    const a = (s / segments) * Math.PI * 2;
    const [cos, sin] = [Math.cos(a), Math.sin(a)];
    for (let i = 0; i < rows; i++) {
      const [r, y] = profile[i];
      const [nr, ny] = flat[i];
      positions.push(r * cos, y, -r * sin);
      normals.push(nr * cos, ny, -nr * sin);
    }
  }
  for (let s = 0; s < segments; s++) {
    for (let i = 0; i < rows - 1; i++) {
      const a = s * rows + i;
      const b = (s + 1) * rows + i;
      indices.push(a, a + 1, b + 1, a, b + 1, b);
    }
  }
  return { positions, normals, indices };
}

/** A sphere, as a profile swept from the bottom pole to the top. */
const sphereProfile = (r, rings = 16, t0 = 0, t1 = Math.PI) =>
  Array.from({ length: rings + 1 }, (_, i) => {
    const t = t0 + ((t1 - t0) * i) / rings;
    return [Math.sin(t) * r, -Math.cos(t) * r];
  });

const sphere = (r, segments = 24, rings = 16) => lathe(sphereProfile(r, rings), segments);

/** The part of a sphere above `yFrom` — a skullcap, for hair and hat linings. */
const dome = (r, yFrom, segments = 28, rings = 12) =>
  lathe(sphereProfile(r, rings, Math.acos(Math.min(1, Math.max(-1, -yFrom / r))), Math.PI), segments);

/** A tapered tube: `steps` of [radius, y], built straight from two radii. */
const taper = (r0, r1, y0, y1, steps = 6, segments = 14) =>
  lathe(
    Array.from({ length: steps + 1 }, (_, i) => {
      const t = i / steps;
      // Eased so limbs and locks read as rounded rather than as cones.
      return [r0 + (r1 - r0) * t ** 0.8, y0 + (y1 - y0) * t];
    }),
    segments,
  );

/**
 * Sweep a circle along a 2D path in XY. Used for the two mouths, which are
 * arcs and the one thing on this character a lathe cannot make.
 */
function tube(path, radius, sides = 8) {
  const positions = [];
  const normals = [];
  const indices = [];
  for (let i = 0; i < path.length; i++) {
    const [px, py] = path[i];
    const [ax, ay] = path[Math.max(0, i - 1)];
    const [bx, by] = path[Math.min(path.length - 1, i + 1)];
    const [tx, ty] = [bx - ax, by - ay];
    const len = Math.hypot(tx, ty) || 1;
    // In-plane normal, and Z, span the ring's plane.
    const [nx, ny] = [-ty / len, tx / len];
    for (let s = 0; s <= sides; s++) {
      const a = (s / sides) * Math.PI * 2;
      const [c, sn] = [Math.cos(a), Math.sin(a)];
      positions.push(px + nx * c * radius, py + ny * c * radius, sn * radius);
      normals.push(nx * c, ny * c, sn);
    }
  }
  const ring = sides + 1;
  for (let i = 0; i < path.length - 1; i++) {
    for (let s = 0; s < sides; s++) {
      const a = i * ring + s;
      const b = (i + 1) * ring + s;
      indices.push(a, b, b + 1, a, b + 1, a + 1);
    }
  }
  return { positions, normals, indices };
}

/** Extrude a 2D polygon along Z, flat-shaded. The hat's star, and only that. */
function extrude(poly, depth) {
  const positions = [];
  const indices = [];
  const n = poly.length;
  const h = depth / 2;
  for (const z of [h, -h]) for (const [x, y] of poly) positions.push(x, y, z);
  // Fanned from the centroid, so a concave outline (a star is very concave)
  // still triangulates correctly.
  const cx = poly.reduce((s, p) => s + p[0], 0) / n;
  const cy = poly.reduce((s, p) => s + p[1], 0) / n;
  const frontC = positions.length / 3;
  positions.push(cx, cy, h);
  const backC = positions.length / 3;
  positions.push(cx, cy, -h);
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    indices.push(frontC, i, j);
    indices.push(backC, n + j, n + i);
    indices.push(i, n + i, n + j, i, n + j, j);
  }
  return unweld({ positions, indices });
}

/** Gives every triangle its own normal, for anything that should read faceted. */
function unweld({ positions, indices }) {
  const p = [];
  const nrm = [];
  const idx = [];
  const at = (i) => [positions[i * 3], positions[i * 3 + 1], positions[i * 3 + 2]];
  for (let i = 0; i < indices.length; i += 3) {
    const tri = [indices[i], indices[i + 1], indices[i + 2]];
    const [a, b, c] = tri.map(at);
    const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    const v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    let n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    const len = Math.hypot(...n) || 1;
    n = n.map((x) => x / len);
    for (const t of tri) {
      idx.push(p.length / 3);
      p.push(...at(t));
      nrm.push(...n);
    }
  }
  return { positions: p, normals: nrm, indices: idx };
}

/** A five-pointed star outline, for the hat badge. */
const starOutline = (outer, inner) =>
  Array.from({ length: 10 }, (_, i) => {
    const a = (i / 10) * Math.PI * 2 + Math.PI / 2;
    const r = i % 2 ? inner : outer;
    return [Math.cos(a) * r, Math.sin(a) * r];
  });

/** A ring around Y: a small circle swept at distance R. Belt, hat band, staff collar. */
const torus = (R, r, segments = 20, rings = 10) =>
  lathe(
    Array.from({ length: rings + 1 }, (_, i) => {
      const t = (i / rings) * Math.PI * 2;
      return [R + Math.cos(t) * r, Math.sin(t) * r];
    }),
    segments,
  );

// ---------------------------------------------------------------------------
// Pip.
//
// Proportions are chibi and the numbers are deliberate: the head is a 0.36
// sphere on a 1.78-unit figure, so it is roughly two fifths of the total
// height, and the eyes are 0.17 across on a 0.72 face. At the sizes this is
// actually drawn — 36 to 112 pixels — that is the difference between a face
// and a smudge.
//
// Everything below is positioned against the head sphere's own surface rather
// than by eye, which is why the z coordinates look arbitrary: they are
// sqrt(r^2 - x^2 - y^2) for the feature's own x and y, pulled back a little so
// the feature sits in the face instead of floating off it.
// ---------------------------------------------------------------------------
const HEAD_R = 0.36;
const HEAD_Y = 0.27;

/** A flared robe, closed at the hem so there is no hole to see up. */
const ROBE = [
  [0.0, -0.66], [0.19, -0.665], [0.31, -0.652], [0.385, -0.612], [0.4, -0.55],
  [0.382, -0.45], [0.348, -0.34], [0.302, -0.23], [0.262, -0.14], [0.232, -0.06],
  [0.215, 0.0], [0.2, 0.03],
];

/** A short cape over the shoulders: out, down, and back up its own underside. */
const CAPE = [
  [0.19, 0.055], [0.26, -0.005], [0.33, -0.07], [0.375, -0.135], [0.37, -0.152],
  [0.318, -0.098], [0.25, -0.032], [0.19, 0.03],
];

/** The hat brim, curving down to a thin edge and back along its underside. */
const BRIM = [
  [0.31, 0.25], [0.4, 0.238], [0.48, 0.218], [0.55, 0.186], [0.585, 0.16],
  [0.575, 0.146], [0.52, 0.176], [0.44, 0.206], [0.36, 0.226], [0.31, 0.236],
];

/** The cone, slightly bellied rather than straight, so it reads as cloth. */
const HAT_CONE = [
  [0.315, 0.245], [0.3, 0.3], [0.265, 0.38], [0.218, 0.46], [0.166, 0.54],
  [0.116, 0.61], [0.076, 0.665], [0.05, 0.7],
];

const MESHES = {
  head: { geometry: sphere(HEAD_R, 30, 20), material: MAT.skin },
  hairCap: { geometry: dome(0.385, 0.08, 30, 14), material: MAT.hair },
  hairBack: { geometry: sphere(0.3, 26, 16), material: MAT.hair },
  lock: { geometry: taper(0.075, 0.025, 0, -0.34, 7, 12), material: MAT.hair },
  bang: { geometry: taper(0.062, 0.012, 0, -0.1, 6, 10), material: MAT.hair },

  sclera: { geometry: sphere(0.085, 20, 14), material: MAT.sclera },
  iris: { geometry: sphere(0.068, 20, 14), material: MAT.iris },
  pupil: { geometry: sphere(0.036, 16, 10), material: MAT.pupil },
  glint: { geometry: sphere(0.024, 12, 8), material: MAT.glint },
  lash: { geometry: sphere(0.075, 16, 10), material: MAT.pupil },
  brow: { geometry: sphere(0.05, 12, 8), material: MAT.hairDark },
  blush: { geometry: sphere(0.055, 14, 10), material: MAT.blush },
  mouthSmile: {
    geometry: tube([[-0.052, 0.014], [-0.026, -0.004], [0, -0.013], [0.026, -0.004], [0.052, 0.014]], 0.013),
    material: MAT.mouth,
  },
  mouthFrown: {
    geometry: tube([[-0.046, -0.012], [-0.023, 0.005], [0, 0.011], [0.023, 0.005], [0.046, -0.012]], 0.012),
    material: MAT.mouth,
  },

  brim: { geometry: lathe(BRIM, 32), material: MAT.hat },
  cone: { geometry: lathe(HAT_CONE, 32), material: MAT.hat },
  hatBand: { geometry: torus(0.303, 0.035, 28, 10), material: MAT.gold },
  star: { geometry: extrude(starOutline(0.078, 0.034), 0.022), material: MAT.gold },
  tipCone: { geometry: taper(0.05, 0.012, 0, 0.22, 6, 12), material: MAT.hat },
  tipBall: { geometry: sphere(0.032, 12, 8), material: MAT.gold },

  robe: { geometry: lathe(ROBE, 28), material: MAT.robe },
  cape: { geometry: lathe(CAPE, 28), material: MAT.trim },
  belt: { geometry: torus(0.33, 0.028, 24, 10), material: MAT.gold },
  hem: { geometry: torus(0.395, 0.024, 26, 10), material: MAT.trim },
  arm: { geometry: taper(0.075, 0.058, 0, -0.28, 6, 12), material: MAT.robeDark },
  hand: { geometry: sphere(0.086, 16, 12), material: MAT.skin },
  boot: { geometry: sphere(0.085, 16, 12), material: MAT.boot },

  staff: { geometry: taper(0.026, 0.02, -0.34, 0.46, 5, 10), material: MAT.wood },
  staffRing: { geometry: torus(0.098, 0.014, 18, 8), material: MAT.gold },
  orb: { geometry: sphere(0.084, 20, 14), material: MAT.orb },
  spark: { geometry: sphere(0.016, 10, 6), material: MAT.orb },
};

/**
 * The rig.
 *
 * `root` carries the whole figure so a jump or a spin moves everything. `head`
 * hangs off `body` so a slump carries the head with it, and the hat and every
 * facial feature hang off `head` so a tilt takes the face along. The staff is
 * parented to the right hand and counter-rotated, which is why it stays
 * upright while the arm swings and why raising the arm raises the staff for
 * free.
 *
 * Each eye is a group of five: sclera, iris, pupil and two catchlights, each
 * one a squashed sphere a little in front of the last. Scaling the group is a
 * blink; scaling it partly is every squint the six moods need.
 */
const eye = (side) => {
  const x = 0.145 * side;
  return [
    { name: `eye${side < 0 ? 'L' : 'R'}`, translation: [x, -0.06, 0.298], rotation: [0, 20 * side, 0],
      children: [`sclera${side < 0 ? 'L' : 'R'}`, `iris${side < 0 ? 'L' : 'R'}`, `pupil${side < 0 ? 'L' : 'R'}`, `glintA${side < 0 ? 'L' : 'R'}`, `glintB${side < 0 ? 'L' : 'R'}`, `lash${side < 0 ? 'L' : 'R'}`] },
    { name: `sclera${side < 0 ? 'L' : 'R'}`, mesh: 'sclera', scale: [1, 1.2, 0.3] },
    { name: `iris${side < 0 ? 'L' : 'R'}`, mesh: 'iris', translation: [0, -0.006, 0.018], scale: [1, 1.12, 0.26] },
    { name: `pupil${side < 0 ? 'L' : 'R'}`, mesh: 'pupil', translation: [0, -0.008, 0.03], scale: [1, 1.05, 0.24] },
    { name: `glintA${side < 0 ? 'L' : 'R'}`, mesh: 'glint', translation: [-0.026, 0.04, 0.042], scale: [1, 1, 0.35] },
    { name: `glintB${side < 0 ? 'L' : 'R'}`, mesh: 'glint', translation: [0.03, -0.028, 0.042], scale: [0.5, 0.5, 0.18] },
    // Sits in front of the iris but behind the catchlights, so the highlights
    // stay on top of it the way a real highlight sits on the wet surface.
    { name: `lash${side < 0 ? 'L' : 'R'}`, mesh: 'lash', translation: [0, 0.078, 0.018], scale: [1.35, 0.34, 0.34] },
  ];
};

const NODES = [
  { name: 'root', children: ['body'] },
  { name: 'body', mesh: 'robe', children: ['cape', 'belt', 'hem', 'armL', 'armR', 'bootL', 'bootR', 'head'] },
  { name: 'cape', mesh: 'cape' },
  { name: 'belt', mesh: 'belt', translation: [0, -0.22, 0] },
  { name: 'hem', mesh: 'hem', translation: [0, -0.6, 0] },
  { name: 'bootL', mesh: 'boot', translation: [-0.135, -0.675, 0.055], scale: [1, 0.72, 1.45] },
  { name: 'bootR', mesh: 'boot', translation: [0.135, -0.675, 0.055], scale: [1, 0.72, 1.45] },

  { name: 'armL', mesh: 'arm', translation: [-0.215, -0.05, 0.05], rotation: [0, 0, -40], children: ['handL'] },
  { name: 'handL', mesh: 'hand', translation: [0, -0.28, 0] },
  { name: 'armR', mesh: 'arm', translation: [0.215, -0.05, 0.05], rotation: [0, 0, 40], children: ['handR'] },
  { name: 'handR', mesh: 'hand', translation: [0, -0.28, 0], children: ['staff'] },
  // Counter-rotated out of the arm's swing so it hangs plumb at rest.
  { name: 'staff', mesh: 'staff', rotation: [-6, 0, -40], children: ['staffRing', 'orb', 'sparkA', 'sparkB', 'sparkC'] },
  { name: 'staffRing', mesh: 'staffRing', translation: [0, 0.485, 0], rotation: [90, 0, 0] },
  { name: 'orb', mesh: 'orb', translation: [0, 0.485, 0] },
  { name: 'sparkA', mesh: 'spark', translation: [0.1, 0.56, 0.02] },
  { name: 'sparkB', mesh: 'spark', translation: [-0.095, 0.545, -0.03] },
  { name: 'sparkC', mesh: 'spark', translation: [0.01, 0.62, 0.01] },

  { name: 'head', mesh: 'head', translation: [0, HEAD_Y, 0],
    children: ['hairBack', 'hairCap', 'lockL', 'lockR', 'bang1', 'bang2', 'bang3',
      'eyeL', 'eyeR', 'browL', 'browR', 'blushL', 'blushR', 'mouthSmile', 'mouthFrown', 'hat'] },
  { name: 'hairBack', mesh: 'hairBack', translation: [0, -0.1, -0.14], scale: [1.18, 1.05, 1] },
  { name: 'hairCap', mesh: 'hairCap' },
  { name: 'lockL', mesh: 'lock', translation: [-0.31, 0.06, 0.02], rotation: [0, 0, 8] },
  { name: 'lockR', mesh: 'lock', translation: [0.31, 0.06, 0.02], rotation: [0, 0, -8] },
  { name: 'bang1', mesh: 'bang', translation: [-0.175, 0.085, 0.275], rotation: [0, 0, 13] },
  { name: 'bang2', mesh: 'bang', translation: [0.01, 0.095, 0.305], rotation: [0, 0, -6] },
  { name: 'bang3', mesh: 'bang', translation: [0.175, 0.085, 0.275], rotation: [0, 0, -15] },

  ...eye(-1),
  ...eye(1),

  { name: 'browL', mesh: 'brow', translation: [-0.15, 0.075, 0.3], rotation: [0, -20, 0], scale: [1.5, 0.22, 0.3] },
  { name: 'browR', mesh: 'brow', translation: [0.15, 0.075, 0.3], rotation: [0, 20, 0], scale: [1.5, 0.22, 0.3] },
  { name: 'blushL', mesh: 'blush', translation: [-0.225, -0.15, 0.222], rotation: [0, -35, 0], scale: [1.5, 0.92, 0.22] },
  { name: 'blushR', mesh: 'blush', translation: [0.225, -0.15, 0.222], rotation: [0, 35, 0], scale: [1.5, 0.92, 0.22] },
  // Two mouths, swapped by scaling one of them away. A smile cannot be turned
  // into a frown by scaling it, and node transforms are all a clip can drive.
  { name: 'mouthSmile', mesh: 'mouthSmile', translation: [0, -0.2, 0.286] },
  { name: 'mouthFrown', mesh: 'mouthFrown', translation: [0, -0.2, 0.286], scale: [0.001, 0.001, 0.001] },

  { name: 'hat', children: ['brim', 'cone', 'hatBand', 'star', 'hatTip'] },
  { name: 'brim', mesh: 'brim' },
  { name: 'cone', mesh: 'cone' },
  { name: 'hatBand', mesh: 'hatBand', translation: [0, 0.285, 0] },
  { name: 'star', mesh: 'star', translation: [0, 0.285, 0.335] },
  // Its own node so the point can flop — the single most expressive thing on
  // the whole figure, and it costs one rotation track per clip.
  { name: 'hatTip', translation: [0, 0.7, 0], rotation: [10, 0, -38], children: ['tipCone', 'tipBall'] },
  { name: 'tipCone', mesh: 'tipCone' },
  { name: 'tipBall', mesh: 'tipBall', translation: [0, 0.23, 0] },
];

// ---------------------------------------------------------------------------
// Poses, as animation clips.
//
// A rotation track replaces a node's rotation outright, so every euler below
// is absolute and includes the rest pose's own components — the brows, for
// instance, are splayed 20 degrees around Y to sit on the curve of the face,
// and every brow keyframe has to carry that or they would snap flat.
// ---------------------------------------------------------------------------
const DEG = Math.PI / 180;

/** three.js's default XYZ Euler order, so the clips read the same in-engine. */
function quat([rx, ry, rz]) {
  const [x, y, z] = [rx * DEG * 0.5, ry * DEG * 0.5, rz * DEG * 0.5];
  const [c1, c2, c3] = [Math.cos(x), Math.cos(y), Math.cos(z)];
  const [s1, s2, s3] = [Math.sin(x), Math.sin(y), Math.sin(z)];
  return [
    s1 * c2 * c3 + c1 * s2 * s3,
    c1 * s2 * c3 - s1 * c2 * s3,
    c1 * c2 * s3 + s1 * s2 * c3,
    c1 * c2 * c3 - s1 * s2 * s3,
  ];
}

