// ---------------------------------------------------------------------------
// glTF 2.0 binary container.
// ---------------------------------------------------------------------------
const FLOAT = 5126;
const UNSIGNED_SHORT = 5123;
const ARRAY_BUFFER = 34962;
const ELEMENT_ARRAY_BUFFER = 34963;
const COMPONENTS = { SCALAR: 1, VEC3: 3, VEC4: 4 };

function buildGltf() {
  const chunks = [];
  let offset = 0;
  const bufferViews = [];
  const accessors = [];

  function view(typed, target) {
    const bytes = Buffer.from(typed.buffer, typed.byteOffset, typed.byteLength);
    const pad = (4 - (offset % 4)) % 4;
    if (pad) {
      chunks.push(Buffer.alloc(pad));
      offset += pad;
    }
    const v = { buffer: 0, byteOffset: offset, byteLength: bytes.length };
    if (target) v.target = target;
    bufferViews.push(v);
    chunks.push(bytes);
    offset += bytes.length;
    return bufferViews.length - 1;
  }

  /** `bounds` is required by the spec for POSITION and for animation inputs. */
  function accessor(typed, type, componentType, target, bounds = false) {
    const stride = COMPONENTS[type];
    const a = { bufferView: view(typed, target), componentType, count: typed.length / stride, type };
    if (bounds) {
      const min = new Array(stride).fill(Infinity);
      const max = new Array(stride).fill(-Infinity);
      for (let i = 0; i < typed.length; i++) {
        const c = i % stride;
        if (typed[i] < min[c]) min[c] = typed[i];
        if (typed[i] > max[c]) max[c] = typed[i];
      }
      a.min = min;
      a.max = max;
    }
    accessors.push(a);
    return accessors.length - 1;
  }

  const meshes = [];
  const meshIndex = {};
  for (const [name, { geometry, material }] of Object.entries(MESHES)) {
    if (geometry.positions.length / 3 > 65535) throw new Error(`${name} needs 32-bit indices`);
    const position = accessor(new Float32Array(geometry.positions), 'VEC3', FLOAT, ARRAY_BUFFER, true);
    const normal = accessor(new Float32Array(geometry.normals), 'VEC3', FLOAT, ARRAY_BUFFER);
    const indices = accessor(new Uint16Array(geometry.indices), 'SCALAR', UNSIGNED_SHORT, ELEMENT_ARRAY_BUFFER);
    meshIndex[name] = meshes.length;
    meshes.push({ name, primitives: [{ attributes: { POSITION: position, NORMAL: normal }, indices, material }] });
  }

  const nodeIndex = Object.fromEntries(NODES.map((n, i) => [n.name, i]));
  const nodes = NODES.map((n) => {
    const node = { name: n.name };
    if (n.mesh !== undefined) node.mesh = meshIndex[n.mesh];
    if (n.translation) node.translation = n.translation;
    if (n.rotation) node.rotation = quat(n.rotation);
    if (n.scale) node.scale = n.scale;
    if (n.children) {
      node.children = n.children.map((c) => {
        if (nodeIndex[c] === undefined) throw new Error(`${n.name} names a missing child: ${c}`);
        return nodeIndex[c];
      });
    }
    return node;
  });

  const animations = CLIPS.map((clip) => {
    const samplers = [];
    const channels = [];
    for (const t of clip.tracks) {
      if (nodeIndex[t.node] === undefined) throw new Error(`${clip.name} targets a missing node: ${t.node}`);
      if (t.times.length !== t.values.length) throw new Error(`${clip.name}/${t.node}: key count mismatch`);
      const type = t.path === 'rotation' ? 'VEC4' : 'VEC3';
      const input = accessor(new Float32Array(t.times), 'SCALAR', FLOAT, undefined, true);
      const output = accessor(new Float32Array(t.values.flat()), type, FLOAT);
      samplers.push({ input, output, interpolation: 'LINEAR' });
      channels.push({ sampler: samplers.length - 1, target: { node: nodeIndex[t.node], path: t.path } });
    }
    return { name: clip.name, samplers, channels };
  });

  const binary = Buffer.concat(chunks);
  return {
    json: {
      asset: {
        version: '2.0',
        generator: 'job-switch-tracker scripts/make-character-model.mjs — original geometry, generated for this project',
        copyright: 'Original work, generated for this project.',
      },
      scene: 0,
      scenes: [{ nodes: [nodeIndex.root] }],
      nodes,
      meshes,
      materials: MATERIALS,
      accessors,
      bufferViews,
      buffers: [{ byteLength: binary.length }],
      animations,
    },
    binary,
  };
}

/** 12-byte header, a JSON chunk padded with spaces, a BIN chunk padded with zeros. */
function toGlb({ json, binary }) {
  const pad = (buf, to, filler) => {
    const extra = (to - (buf.length % to)) % to;
    return extra ? Buffer.concat([buf, Buffer.alloc(extra, filler)]) : buf;
  };
  const jsonChunk = pad(Buffer.from(JSON.stringify(json), 'utf8'), 4, 0x20);
  const binChunk = pad(binary, 4, 0);

  const header = Buffer.alloc(12);
  header.writeUInt32LE(0x46546c67, 0); // "glTF"
  header.writeUInt32LE(2, 4);
  header.writeUInt32LE(12 + 8 + jsonChunk.length + 8 + binChunk.length, 8);

  const chunkHeader = (length, type) => {
    const b = Buffer.alloc(8);
    b.writeUInt32LE(length, 0);
    b.writeUInt32LE(type, 4);
    return b;
  };
  return Buffer.concat([
    header,
    chunkHeader(jsonChunk.length, 0x4e4f534a), // "JSON"
    jsonChunk,
    chunkHeader(binChunk.length, 0x004e4942), // "BIN\0"
    binChunk,
  ]);
}

/**
 * Attribution, written by the same script that writes the geometry so the two
 * cannot drift apart. `source` is omitted rather than filled in with something
 * plausible: there is no source, and a blank field is the honest answer. No
 * `accent` either — a character's accent has to clear the same contrast floors
 * every shipped token does, and this palette clears them in light mode only,
 * so applying it would repaint half the themes and not the other half.
 */
const META = {
  id: 'pip',
  name: 'Pip',
  artist: 'Generated for this project by scripts/make-character-model.mjs',
  license: 'Original work, generated for this project',
  lines: {
    cheer: ['One down.', 'Noted!', 'That one is yours.', 'Neat.', 'Onward!'],
    milestone: ['A whole set — look at that.', 'Every last one.', 'That is the lot!'],
    idle: ['Ready when you are.', 'One at a time.', 'Take the next one.', 'Still here.'],
  },
};

const glb = toGlb(buildGltf());
mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(join(OUT_DIR, 'model.glb'), glb);
writeFileSync(join(OUT_DIR, 'meta.json'), JSON.stringify(META, null, 2) + '\n');
console.log(`pip/model.glb  ${(glb.length / 1024).toFixed(1)} KB`);
console.log(`pip/meta.json  ${CLIPS.length} poses: ${CLIPS.map((c) => c.name).join(', ')}`);
